source(file.path(commandArgs(TRUE)[1],'code/plot_common.R'));tabs<-file.path(root,'tables');d<-fread(file.path(tabs,'information_strata.tsv'));if(!nrow(d))quit(save='no');d[,information_band:=factor(information_band,levels=c('<20','20-99','100-499','>=500','All'))];cols<-c('<20'='#d5d5d5','20-99'='#b2df8a','100-499'='#33a02c','>=500'='#006d2c');p<-ggplot(d[information_band!='All'],aes(section,fraction,fill=information_band))+geom_col()+scale_fill_manual(values=cols,name='nFeature band')+scale_y_continuous(labels=scales::percent)+jin_theme()+theme(axis.text.x=element_text(angle=30,hjust=1))+labs(x=NULL,y='Fraction of analysis bins');export(p,'information_composition',10,6,8)
z<-fread(file.path(tabs,'reference_disagreement_strata.tsv'));z<-z[denominator=='both_candidates'&information_band!='All'];z[,information_band:=factor(information_band,levels=c('<20','20-99','100-499','>=500'))];p<-ggplot(z,aes(information_band,disagree_fraction,color=section,group=section))+geom_line(linewidth=.4)+geom_point(size=2)+facet_wrap(~level,nrow=1)+scale_color_manual(values=c(Cervilla='#f5b264',D1_Johnson='#8b78b8',UC_SCC='#2878b5',MPBC1='#57c1b5',MPBC2='#b64f81'),name='Section')+scale_y_continuous(labels=scales::percent)+jin_theme()+labs(x='nFeature band (descriptive)',y='Reference disagreement (both candidates)');export(p,'reference_disagreement_by_information',13,6,11)
p<-ggplot(d[information_band!='All'],aes(information_band,expanded_keratin_collagen_ge2,color=section,group=section))+geom_line(linewidth=.4)+geom_point(size=2)+scale_color_manual(values=c(Cervilla='#f5b264',D1_Johnson='#8b78b8',UC_SCC='#2878b5',MPBC1='#57c1b5',MPBC2='#b64f81'),name='Section')+scale_y_continuous(labels=scales::percent)+jin_theme()+labs(x='nFeature band (descriptive)',y='Expanded keratin + collagen detection (>=2 each)');export(p,'raw_panel_codetection_by_information',10,6,8)
